// TH16 v1.00a Extra dual-midboss spell 1.
// Source entries: st07mbs.ecl.txt MBossCard1:156-193,
//                 st07mbs2.ecl.txt MBossBCard1:145-179.
// Entry state taken from MBoss:6-55 / MBossB:77-120: both bosses finish
// their entry glide at (80,128) / (-80,128), hurtbox 24, hitbox 20.

const TH16_BALL: int = 416;          // source etSprite type 4, color 2
const TIME_LIMIT: int = 3124;        // 120 opening buffer + 3000 source timer + 4
const OPENING_BUFFER: int = 120;

// st07mbs.ecl.txt:316-341 (etSprite 4,2; etAim 2; one aimed bullet).
// etEx type2 (ANIM a=1) is the omitted birth animation; its approved
// birth retreat position -= 4*velocity is kept as a 6px backward spawn offset.
async sub ecir_fire() {
    wait(10 + rand(30));             // source wait(10 + $RAND % 30)
    for i in 0..400 {                // source loop bound $B = 400
        var a: angle = aim_player();
        _ = fire(TH16_BALL, 2,
                 $self_x - 6fx * cos(a),
                 $self_y - 6fx * sin(a),
                 1.5fx, a, none, none);
        wait(50);
    }
}

// st07mbs.ecl.txt:211-264 child MBossCard1_ECir00 main task.
async sub ecir_main() {
    set_invuln(65535);
    set_hurtbox(12fx);               // source setHurtbox(24,24)
    set_hitbox(8fx);                 // source setHitbox(16,16)
    wait(60);
    move_vel(0, 90deg, 2fx, EASE_LINEAR);
    move_speed(68, 6fx, EASE_QUAD_IN);   // +68: absolute source time 68
    wait(8);
    move_speed(60, 0fx, EASE_QUAD_IN);   // +60: source time 128
    wait(60);
    move_vel(0, aim_player(), 0fx, EASE_LINEAR);  // %ANGLE_PLAYER at t=128
    spawn ecir_fire();
    move_speed(120, 1fx, EASE_QUAD_IN);
    wait(180);                       // source time 308
    move_angle(120, aim_player(), EASE_QUAD_IN);
    wait(180);                       // source time 488
    move_angle(120, aim_player(), EASE_QUAD_IN);
    loop { wait(1000); }
}

// st07mbs.ecl.txt:266-291 MBossCard1_at: 3 groups x 8 mirrored pairs,
// 30 frames between pairs, 60 frames between outer iterations.
async sub card1_spawner() {
    loop {
        for group in 0..3 {
            var ax: fx = 8fx;        // source %A = _f(8)
            for i in 0..8 {
                _ = spawn_enemy(ax, -32fx, 100, 0, 1000, 0, ecir_main);
                _ = spawn_enemy(0fx - ax, -32fx, 100, 0, 1000, 0, ecir_main);
                ax = ax + 24fx;      // source %A = %A + _f(24)
                wait(30);
            }
        }
        wait(60);
    }
}

// st07mbs.ecl.txt MBossCard1:156-193. Spell declaration, interrupts and
// presentation are carried by the phase/control shell; the 90-frame gate
// and the 480-frame idle loop stay on the boss.
async sub boss_a_main() {
    set_invuln(65535);
    set_hurtbox(24fx);               // source setHurtbox(48,48)
    set_hitbox(20fx);                // source setHitbox(40,40)
    move_vel(0, 0deg, 0fx, EASE_LINEAR);  // source moveVel(0,0)
    wait(90);
    spawn card1_spawner();
    loop { wait(240); wait(240); }    // source 480-frame reset loop
}

// st07mbs2.ecl.txt MBossBCard1:145-179. This boss declares the shared
// spell and idles; it has no own emitter in the card.
async sub boss_b_main() {
    set_invuln(65535);
    set_hurtbox(24fx);
    set_hitbox(20fx);
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    wait(90);
    loop { wait(240); wait(240); }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(80fx, 128fx, 1700, 0, 0, 0, boss_a_main);
    _ = spawn_enemy(-80fx, 128fx, 1700, 0, 0, 0, boss_b_main);
    loop { wait(1); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
